// Static sample-library art + metadata, generated by build_landing_art.py
// from samples/ (re-run it when the library changes). Lets the landing page
// and the phone home screen show samples without calling the API or
// downloading feature files.
import samples from '../assets/landing/samples.json'

const thumbs = import.meta.glob('../assets/landing/thumbs/*.png', {
  eager: true, query: '?url', import: 'default',
})

export const SAMPLES = samples

// URL of a sample's spectrogram thumbnail, or null if it has none.
export function thumbFor(id) {
  return thumbs[`../assets/landing/thumbs/${id}.png`] || null
}

export function providerName(sample) {
  return sample.provider === 'freesound' ? 'Freesound' : 'Xeno-canto'
}
